def launch_desktop_window(url):
    # Launch dedicated standalone application window (no browser address bar/tabs)
    browser_candidates = [
        r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
        r"C:\Program Files\Microsoft\Edge\Application\msedge.exe",
        r"C:\Program Files\Google\Chrome\Application\chrome.exe",
        r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe",
        shutil.which("msedge"),
        shutil.which("chrome")
    ]
    for b_path in browser_candidates:
        if b_path and os.path.exists(b_path):
            try:
                subprocess.Popen([b_path, f"--app={url}"])
                return True
            except Exception:
                pass
    # Fallback to standard system browser
    webbrowser.open(url)
    return True

def run_flask_server(port):
    log = logging.getLogger("werkzeug")
    log.setLevel(logging.ERROR)
    app.run(host="127.0.0.1", port=port, debug=False, use_reloader=False, threaded=True)

def find_available_port(start_port=5005):
    import socket
    for p in range(start_port, start_port + 50):
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            if s.connect_ex(('127.0.0.1', p)) != 0:
                return p
    return start_port

def main():
    # Direct CLI extraction if target path is supplied as argument (e.g. python teams_forensic_tool.py E:\IndexedDB --case Sandeep)
    if len(sys.argv) > 1 and not sys.argv[1].startswith("-"):
        cli_target = sys.argv[1].strip()
        cli_case = None
        for i in range(2, len(sys.argv)):
            if sys.argv[i].lower() in ("--case", "-c", "--name", "-name") and i + 1 < len(sys.argv):
                cli_case = sys.argv[i+1].strip()
                break
            elif not sys.argv[i].startswith("-") and not cli_case:
                cli_case = sys.argv[i].strip()
        if os.path.exists(cli_target):
            print("=" * 80)
            print("MICROSOFT TEAMS FORENSIC SUITE - DIRECT CLI PARSER")
            print(f"Target Evidence Path : {cli_target}")
            print("=" * 80)
            engine = TeamsForensicEngine(cli_target, case_name=cli_case)
            engine.run_pipeline()
            viewer_path = os.path.join(engine.case_dir, "Teams_Forensic_Viewer.html")
            print("\n" + "=" * 80)
            print(f"[Done] Case successfully exported to: {engine.case_dir}")
            print(f"[Viewer] Interactive Report: {viewer_path}")
            print("=" * 80)
            try:
                import webbrowser
                webbrowser.open(viewer_path)
            except Exception:
                pass
            return
        else:
            print(f"[Error] Specified evidence path does not exist: {cli_target}")
            sys.exit(1)

    import socket
    port = find_available_port(5005)
    url = f"http://127.0.0.1:{port}"
    print("=" * 80)
    print("MICROSOFT TEAMS FORENSIC SUITE - PYTHON APPLICATION")
    print(f"Tool directory   : {TOOL_DIR}")
    print(f"Cases directory  : {CASES_DIR}")
    print(f"Server endpoint  : {url}")
    print("Starting desktop application...")
    print("=" * 80)

    # Start Flask server thread with multi-threading
    flask_thread = threading.Thread(target=run_flask_server, args=(port,), daemon=True)
    flask_thread.start()

    # Actively wait until the local server is listening before opening window
    for _ in range(60):
        time.sleep(0.05)
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            if s.connect_ex(('127.0.0.1', port)) == 0:
                break

    # Launch standalone application window
    launch_desktop_window(url)
    print(f"[Ready] Application running at {url}")
    print("Press Ctrl+C in this terminal window to stop the server.")

    # Keep Python process alive
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nStopping Microsoft Teams Forensic Suite...")
        sys.exit(0)

if __name__ == "__main__":
    main()
